abstract class PaymentProcessor {
    protected String merchantId;

    public PaymentProcessor(String merchantId) {
        this.merchantId = merchantId;
    }

    // LEGAL: protected abstract method with parameters and return type
    protected abstract boolean authorize(String account, double amount);

    // LEGAL: public abstract method
    public abstract String getProviderName();

    // Concrete method utilizing the abstract methods!
    public void process(String account, double amount) {
        System.out.println("Attempting settlement via " + getProviderName());
        boolean success = authorize(account, amount);
        System.out.println("Result: " + (success ? "APPROVED" : "DECLINED"));
    }
}

class SquareProcessor extends PaymentProcessor {
    public SquareProcessor(String merchantId) {
        super(merchantId);
    }

    @Override
    public String getProviderName() { return "SQUARE_GATEWAY"; }

    @Override
    protected boolean authorize(String account, double amount) {
        // Concrete child provides implementation
        return amount > 0 && amount <= 5000.0;
    }
}

public class ProcessorApp {
    public static void main(String[] args) {
        PaymentProcessor proc = new SquareProcessor("SQ-9912");
        proc.process("ACC-441", 120.0);
    }
}

