abstract class AbstractShape {
    protected String color;
    public AbstractShape(String color) { this.color = color; }
    public abstract double getArea();
    public void printInfo() {
        System.out.println(color + " shape area: " + String.format("%.2f", getArea()));
    }
}

class Square extends AbstractShape {
    private double side;
    public Square(String color, double side) {
        super(color);
        this.side = side;
    }
    @Override
    public double getArea() {
        return side * side;
    }
}

public class ShapeApp {
    public static void main(String[] args) {
        AbstractShape shape = new Square("Blue", 4.0);
        shape.printInfo();
    }
}

abstract class TextTransformer {
    public abstract String transform(String text);
    public void processAndPrint(String input) {
        System.out.println("Transformed: " + transform(input));
    }
}

class UpperCaseTransformer extends TextTransformer {
    @Override
    public String transform(String text) {
        return text.toUpperCase();
    }
}

class SlugTransformer extends TextTransformer {
    @Override
    public String transform(String text) {
        return text.toLowerCase().replace(' ', '-');
    }
}

public class TransformerApp {
    public static void main(String[] args) {
        TextTransformer[] transformers = new TextTransformer[] {
            new UpperCaseTransformer(),
            new SlugTransformer()
        };
        String sample = "Hello World Java";
        for (TextTransformer t : transformers) {
            t.processAndPrint(sample);
        }
    }
}

abstract class ValidationRule {
    protected String fieldName;
    public ValidationRule(String fieldName) {
        this.fieldName = fieldName;
    }
    public abstract boolean isValid(String value);
    public abstract String getErrorMessage();
    public void validate(String value) {
        if (!isValid(value)) {
            System.out.println(fieldName + ": " + getErrorMessage());
        } else {
            System.out.println(fieldName + ": VALID");
        }
    }
}

class MinLengthRule extends ValidationRule {
    private int minLen;
    public MinLengthRule(String fieldName, int minLen) {
        super(fieldName);
        this.minLen = minLen;
    }
    @Override
    public boolean isValid(String value) {
        return value != null && value.length() >= minLen;
    }
    @Override
    public String getErrorMessage() {
        return "Minimum length " + minLen + " required";
    }
}

class NumericRule extends ValidationRule {
    public NumericRule(String fieldName) {
        super(fieldName);
    }
    @Override
    public boolean isValid(String value) {
        return value != null && value.matches("\\d+");
    }
    @Override
    public String getErrorMessage() {
        return "Must contain digits only";
    }
}

public class ValidationApp {
    public static void main(String[] args) {
        ValidationRule r1 = new MinLengthRule("Username", 5);
        ValidationRule r2 = new NumericRule("ZipCode");
        r1.validate("abc");
        r2.validate("90210");
    }
}

