class SerializedData {
    public String payload;
    public SerializedData(String payload) { this.payload = payload; }
    public String getPayload() { return payload; }
}

class JsonData extends SerializedData {
    public JsonData(String payload) { super(payload); }
    @Override
    public String getPayload() { return "[JSON] " + payload; }
}

class XmlData extends SerializedData {
    public XmlData(String payload) { super(payload); }
    @Override
    public String getPayload() { return "[XML] " + payload; }
}

abstract class DataSerializer {
    public abstract SerializedData serialize(String key, String value);
}

class JsonSerializer extends DataSerializer {
    @Override
    public JsonData serialize(String key, String value) {
        return new JsonData("{\"" + key + "\": \"" + value + "\"}");
    }
}

class XmlSerializer extends DataSerializer {
    @Override
    public XmlData serialize(String key, String value) {
        return new XmlData("<" + key + ">" + value + "</" + key + ">");
    }
}

public class SerializerApp {
    public static void main(String[] args) {
        DataSerializer[] serializers = new DataSerializer[] {
            new JsonSerializer(),
            new XmlSerializer()
        };
        for (DataSerializer s : serializers) {
            System.out.println(s.serialize("user", "alice").getPayload());
        }
    }
}
